"""Bilingual chapter player with the same visual system and explicit evidence links."""
import html,json,re,shutil
from pathlib import Path
SCRIPT=r'''const chapters=CHAPTER_DATA;const film=document.getElementById('film'),host=document.getElementById('chapters');
const stamp=t=>Math.floor(t/60)+':'+String(Math.floor(t%60)).padStart(2,'0');let section='',list,current=-1;
function update(){let n=0;chapters.forEach((c,i)=>{if(film.currentTime+.0005>=c.start)n=i;});host.querySelectorAll('button').forEach((b,i)=>{b.classList.toggle('active',i===n);b.setAttribute('aria-current',i===n?'true':'false');});current=n;document.getElementById('now').textContent=(n+1)+' / '+chapters.length+' · '+chapters[n].title;}
function seek(i){film.currentTime=chapters[i].start;history.replaceState(null,'','#'+chapters[i].id);update();}
chapters.forEach((c,i)=>{if(c.section!==section){section=c.section;const h=document.createElement('h3');h.className='section-title';h.textContent=section;host.appendChild(h);list=document.createElement('div');list.className='chapters';host.appendChild(list);}const b=document.createElement('button');b.dataset.index=i;b.textContent=stamp(c.start)+' · '+c.title;b.onclick=()=>seek(i);list.appendChild(b);const h=document.createElement('h3');h.textContent=stamp(c.start)+' · '+c.title;const p=document.createElement('p');p.textContent=c.text;document.getElementById('transcript').append(h,p);});
for(const e of ['timeupdate','seeked'])film.addEventListener(e,update);
function fromHash(){const i=chapters.findIndex(c=>c.id===location.hash.slice(1));if(i>=0)seek(i);else update();}
film.addEventListener('loadedmetadata',fromHash);window.addEventListener('hashchange',fromHash);
document.getElementById('previous').onclick=()=>seek(Math.max(0,current-1));document.getElementById('next').onclick=()=>seek(Math.min(chapters.length-1,current+1));
document.querySelectorAll('.languages a').forEach(a=>a.addEventListener('click',()=>{a.hash=chapters[Math.max(0,current)].id;}));
'''
def build_pages(out,old,reports):
    css=re.search(r'<style>(.*?)</style>',(old/'index.html').read_text(encoding='utf-8'),re.S)[1]
    css+=' .controls{display:flex;gap:12px;align-items:center;flex-wrap:wrap}#now{flex:1;min-width:240px} .revision{border-left:4px solid #007f82;padding:10px 18px;background:#fffdf7}table{width:100%;border-collapse:collapse}th,td{text-align:left;vertical-align:top;padding:10px;border-bottom:1px solid #c5d2cf} code{overflow-wrap:anywhere} @media(max-width:600px){table{font-size:14px}th,td{padding:5px}}'
    for report in reports:
        lang=report['language'];es=lang=='es';T=lambda a,b:b if es else a;suffix='-es' if es else '';chapters=json.loads((out/f'chapters-{lang}.json').read_text(encoding='utf-8'));dur=f"{int(report['seconds'])//60}:{int(report['seconds'])%60:02}"
        title=T('Between physics and mathematics','Entre física y matemáticas');desc=T('Animated explanations of physical assumptions, exact certificates, recalibrated GHU potentials and measured collider data.','Explicaciones animadas de hipótesis físicas, certificados exactos, potenciales GHU recalibrados y datos medidos de colisionadores.')
        def head(title,desc):return f'<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{desc}"><title>{title} — GHU Lab</title><style>{css}</style></head><body><main>'
        content=head(title,desc)+f'<p class="languages"><a href="index.html" lang="en">English</a> · <a href="index-es.html" lang="es">Castellano</a></p><p><a href="../../index.html">GHU Lab</a> · <a href="../index.html?lang={lang}">{T("General laboratory guide","Guía general del laboratorio")}</a></p><h1>{title}</h1><p>{desc}</p>'
        content+=f'<p class="revision">{T("Updated 17 October: 46 chapters. Chapters 44–46 explain certified matched profiles, residual error bounds and physical scope. The first 28 preserve the original explanations. The extension connects quantization and certificates to physics, then explains potential derivatives, recalibration, the measured CMS spectrum, correlated errors and the scope of validation.","Actualizado el 17 de octubre: 46 capítulos. Los capítulos 44–46 explican perfiles certificados tras matching, cotas de error residual y alcance físico. Los primeros 28 conservan las explicaciones originales. La ampliación conecta cuantización y certificados con la física, y explica derivadas del potencial, recalibración, el espectro medido CMS, errores correlacionados y alcance de las validaciones.")}</p>'
        content+=f'<video id="film" controls playsinline preload="metadata" poster="poster{suffix}.png" src="ghu-mathematics-{lang}.mp4" aria-label="{title}"></video><!-- edition-allow: Requested mathematical film uses only adjacent versioned media. -->'
        content+=f'<p><small>{dur} · 46 {T("chapters","capítulos")} · 1920 × 1080 · 24 fps · {T("Embedded captions; synthetic narration: Microsoft Zira","Subtítulos integrados; narración sintética: Microsoft Helena")}</small></p><div class="controls"><button id="previous">{T("← Previous","← Anterior")}</button><p id="now"></p><button id="next">{T("Next →","Siguiente →")}</button></div>'
        content+='<div class="links">'+''.join(f'<a href="{url}">{label}</a>' for url,label in [(f'ghu-mathematics-{lang}.mp4',T('Download MP4','Descargar MP4')),(f'captions-{lang}.vtt',T('Subtitles','Subtítulos')),(f'transcript-{lang}.txt',T('Transcript','Transcripción')),(f'bridge{suffix}.html',T('Physics, mathematics and certificates','Física, matemáticas y certificados')),('../../proof/index.html',T('Complete certificate catalogue','Catálogo completo de certificados')),('2026-10-12/index'+suffix+'.html',T('Original 29-chapter edition','Edición original de 29 capítulos'))])+'</div>'
        content+=f'<p><a href="../../app/index.html#s=quantization&amp;demo=quantization&amp;lang={lang}">{T("Try the quantization demo","Probar la demo de cuantización")}</a> · <a href="../../guide/{"es/" if es else ""}quantization/index.html">{T("Module guide","Guía del módulo")}</a> · <a href="../../app/index.html#s=kkgluon&amp;lang={lang}">{T("Experimental limits in the laboratory","Límites experimentales en el laboratorio")}</a></p>'
        content+=f'<p><a href="../../app/index.html#s=samepot&amp;demo=hypothesiscompare&amp;lang={lang}">{T("Try the hypothesis comparison demo","Probar la demo de comparación de hipótesis")}</a> · <a href="../../guide/{"es/" if es else ""}hypothesiscompare/index.html">{T("How to use the four plots","Cómo utilizar las cuatro gráficas")}</a> · <a href="2026-10-13/index{suffix}.html">{T("Previous 38-chapter edition","Edición anterior de 38 capítulos")}</a></p>'
        content+=f'<h2>{T("Follow the explanations","Sigue las explicaciones")}</h2><div id="chapters"></div><details><summary>{T("Transcript","Transcripción")}</summary><div id="transcript"></div></details><h2>{T("What the evidence supports","Qué respalda la evidencia")}</h2><p>{T("The first four examples retain their ordinary proofs and 113 executable checks. The catalogue contains 23 quantization declarations, 26 SU(7) declarations and 10 rational hypothesis identities: 59 in five Lean files. Topological interpretation, physical assumptions, numerical checks and file hashes have different roles. None certifies a complete physical model or an observed new particle.","Los primeros cuatro ejemplos conservan sus demostraciones ordinarias y 113 comprobaciones ejecutables. El catálogo contiene 23 declaraciones de cuantización, 26 de SU(7) y 10 identidades racionales de hipótesis: 59 en cinco archivos Lean. La interpretación topológica, las hipótesis físicas, las comprobaciones numéricas y los hashes cumplen funciones distintas. No certifican un modelo físico completo ni una nueva partícula observada.")}</p>'
        content+=f'<p class="revision">{T("New matched-profile evidence: a written functional proof and an independent 228-check Sage replay. The bars are numerical enclosures, not experimental error bars. Download the ZIP from Boundary research; its hash is pinned in inputs.json.","Nueva evidencia de perfiles: demostración funcional escrita y repetición Sage independiente de 228 comprobaciones. Las barras son cotas numéricas, no errores experimentales. Descarga el ZIP desde Investigación de fronteras; inputs.json fija su hash.")} <a href="../../app/index.html#s=anomalies&amp;lang={lang}">{T("Open Boundary research","Abrir Investigación de fronteras")}</a></p>'
        content+=f'<p><a href="proof-notes.html" lang="en">{T("Original mathematical proofs and scope (English)","Demostraciones originales y alcance (inglés)")}</a> · <a href="render-manifest.json">{T("Version, hashes and production checks","Versión, hashes y comprobaciones de producción")}</a></p><script>'+SCRIPT.replace('CHAPTER_DATA',json.dumps(chapters,ensure_ascii=False))+'</script></main></body></html>'
        content=content.replace('#s=kkgluon&amp;lang=', '#s=collider&amp;lang=')
        (out/('index'+suffix+'.html')).write_text(content,encoding='utf-8')
        bridge=head(T('Where the physical and mathematical statements meet','Dónde se encuentran los enunciados físicos y matemáticos'),desc)+f'<p><a href="index{suffix}.html#q1">← {title}</a> · <a href="bridge{"" if es else "-es"}.html">{T("Castellano","English")}</a></p><h1>{T("Assumptions → certificate → module → observable","Hipótesis → certificado → módulo → observable")}</h1><p>{T("A proof certifies an implication. Physics determines whether the actual fields, backgrounds and action satisfy its hypotheses. An experimental comparison additionally needs a prediction with uncertainties.","Una demostración certifica una implicación. La física determina si los campos, fondos y acción reales cumplen sus hipótesis. El contraste experimental necesita además una predicción con incertidumbres.")}</p>'
        rows=[('q1',T('Spectrum and profiles','Espectro y perfiles'),T('The interval operator determines normal eigenvalues; the Gram matrix tests independence of chosen functions.','El operador del intervalo determina autovalores normales; Gram prueba independencia de funciones elegidas.'),T('A physical mass needs scale and kinetic normalization. A family count needs the actual field domain.','Una masa física necesita escala y normalización cinética. Contar familias requiere el dominio real de los campos.')),
        ('q3',T('Universal quantization','Cuantización universal'),'Q = αA + βB + δC; δ = γ − α/4 − β/3; α, β, δ ∈ ℤ.',T('Lean checks coefficient arithmetic. H = S(U(2)×U(3)) and its characteristic-class dictionary must describe the proposed theory.','Lean comprueba la aritmética. H = S(U(2)×U(3)) y sus clases características deben describir la teoría propuesta.')),
        ('q4',T('Spin periods','Períodos espín'),'α, β, 2δ ∈ ℤ.',T('Closed smooth spin four-manifolds have even square periods by Wu parity, supplied outside Lean. The physical orbifold backgrounds are not classified by this theorem.','En variedades espín cerradas suaves 4D, Wu da períodos cuadrados pares; este paso es externo a Lean. El teorema no clasifica los fondos físicos del orbifold.')),
        ('q5',T('Joint U(2) criterion','Criterio conjunto U(2)'),'b₀ ∈ ℤ; b₁ + 2b₀ ∈ 8ℤ. (b₀,b₁)=(1,6): Q=m²+mn+n²=c₁²−c₂.',T('The total characteristic class is integral; an anomaly-free supergravity spectrum is not constructed.','La clase característica total es integral; no se construye un espectro de supergravedad libre de anomalías.')),
        ('q6',T('Parent transfer','Transferencia parental'),'ℓ(R₁)=ℓ(R₂)=0; 6ℓ(v)=16−3p−3q−6r ≡ 1 (mod 3).',T('Conditional on the inherited charged spectrum and the specified ordinary integral Green–Schwarz and parent Chern–Simons responses. Additional sectors or corner terms need a new analysis.','Condicionado al espectro cargado heredado y las respuestas ordinarias integrales Green–Schwarz y Chern–Simons parentales especificadas. Otros sectores o términos de esquina requieren otro análisis.')),
        ('q7',T('Spin(20) lift audit','Auditoría del levantamiento Spin(20)'),'tₐ²=−1; Uₐ=−itₐ; Uₐ²=+1.',T('3,290 exact checks, not Lean. A representation phase is not an ordinary Z₂→Spin(20) lift. A combined action may be possible but must include all fields and interactions, including Ω.','3.290 comprobaciones exactas, no Lean. Una fase de representación no es un levantamiento ordinario Z₂→Spin(20). Puede existir una acción combinada, pero debe incluir todos los campos e interacciones, incluido Ω.')),
        ('q9',T('ATLAS and CMS','ATLAS y CMS'),T('Observed upper limits already used by the laboratory; independent resonance hypotheses and units.','Límites superiores observados ya usados por el laboratorio; hipótesis de resonancia y unidades diferentes.'),T('No map from these quantization coefficients to masses, couplings, widths and cross sections is supplied yet. No agreement, exclusion or new-particle discovery follows for the new examples.','Todavía no se aporta una conexión de estos coeficientes con masas, acoplamientos, anchuras y secciones eficaces. No se deduce acuerdo, exclusión ni descubrimiento para los nuevos ejemplos.'))]
        rows.extend([
        ('h1',T('Potential and couplings','Potencial y acoplamientos'),'H=fH(θ−θH); λn=V⁽ⁿ⁾(θH)/(n! fHⁿ).',T('Canonical local expansion. Lean checks rational polynomial identities; symbolic differentiation checks the logarithm kernel separately.','Expansión local canónica. Lean comprueba identidades polinómicas racionales; la derivación simbólica comprueba por separado el núcleo logarítmico.')),
        ('h2',T('Recalibrated cases','Casos recalibrados'),T('Nine archived calculations at θH=0.1 and mH=125.1 GeV.','Nueve cálculos archivados con θH=0,1 y mH=125,1 GeV.'),T('Nearby local couplings do not establish identical global potentials or insensitivity to arbitrary parameters. Dominant towers; bottom omitted; physical uncertainty unquantified.','Acoplamientos locales próximos no establecen potenciales globales idénticos ni insensibilidad a parámetros arbitrarios. Torres dominantes; bottom omitido; incertidumbre física sin cuantificar.')),
        ('h3',T('Measured CMS spectrum','Espectro medido CMS'),'CMS TOP-20-001: dσ/dm(tt̄), 15 bins, pb/GeV.',T('13 TeV, 137 fb⁻¹, e/μ+jets, parton level, full phase space. Horizontal bars show bin widths; vertical bars are marginal experimental errors. These are measured cross sections, distinct from resonance upper limits.','13 TeV, 137 fb⁻¹, e/μ+jets, nivel de partones, espacio de fases completo. Barras horizontales: anchura del intervalo; verticales: error experimental marginal. Son secciones eficaces medidas, distintas de los límites de resonancias.')),
        ('h4',T('Covariance and normalization','Covarianza y normalización'),'ρᵢⱼ=Cᵢⱼ/√(CᵢᵢCⱼⱼ); C=L diag(d)Lᵀ, d>0.',T('Exact positivity concerns the published decimal matrix. Area normalization uses bin widths and induces one null direction at first order. It does not replace the official normalized covariance.','La positividad exacta corresponde a la matriz decimal publicada. La normalización de área usa anchuras e induce una dirección nula a primer orden. No sustituye la covarianza normalizada oficial.')),
        ('h5',T('Evidence and next steps','Evidencia y próximos pasos'),T('10 rational Lean identities; 15 exact positive pivots; 3 pointwise logarithm derivative bounds.','10 identidades racionales Lean; 15 pivotes positivos exactos; 3 cotas puntuales de derivadas del logaritmo.'),T('Full integral error bounds, global minimum certification and an observed GHU fit remain pending. The approximately 7.4% quartic fit/table discrepancy remains open.','Siguen pendientes cotas de error de la integral completa, certificación del mínimo global y ajuste observado GHU. Sigue abierta la discrepancia aproximada del 7,4 % entre ajuste y tabla cuárticos.'))])
        rows.append(('m3',T('Matched wall profiles','Perfiles de pared tras matching'),'s=1/100; R=1/2; epsilon=1/8; alpha=1/20; Delta C(1/4)>0; Delta C(1/2)>0.',T('Written continuum proof and independently replayed Sage certificate (228 checks). Only two fixed queries; no new Lean formalization, thin-layer rate or complete GHU fit.','Demostración del continuo escrita y certificado Sage repetido independientemente (228 comprobaciones). Solo dos sondas fijas; sin nueva formalización Lean, tasa de capa delgada ni ajuste GHU completo.')))
        bridge+='<table><thead><tr>'+''.join('<th>'+s+'</th>' for s in [T('Chapter','Capítulo'),T('Established statement','Enunciado establecido'),T('Physical scope','Alcance físico')])+'</tr></thead><tbody>'+''.join(f'<tr><td><a href="index{suffix}.html#{i}">{label}</a></td><td>{a}</td><td>{b}</td></tr>' for i,label,a,b in rows)+'</tbody></table>'
        bridge+=f'<h2>{T("Measured data and the figures","Datos medidos y figuras")}</h2><p>{T("The ATLAS curve contains ten published observed 95% CL limits on σ×BR(tt̄), for the RS KK-gluon benchmark with Γ/M=30%, at 13 TeV and 140 fb⁻¹. CMS contains seventy observed narrow qq-resonance limits on σ×B×A, at 13 TeV and 137 fb⁻¹. The vertical axes are logarithmic and use different ranges. Points are the maintained source values; straight segments only guide the eye. They are not measured new-particle production rates. CERN is the laboratory hosting the LHC, not a third independent dataset.","La curva ATLAS contiene diez límites observados publicados al 95% CL sobre σ×BR(tt̄), para el referente de gluón KK RS con Γ/M=30%, a 13 TeV y 140 fb⁻¹. CMS contiene setenta límites observados de resonancia qq estrecha sobre σ×B×A, a 13 TeV y 137 fb⁻¹. Los ejes verticales son logarítmicos y tienen rangos distintos. Los puntos son los valores de las fuentes mantenidas; los segmentos solo guían la vista. No son tasas medidas de producción de una nueva partícula. CERN alberga el LHC; no es un tercer conjunto independiente de datos.")}</p>'
        bridge+=f'<p>{T("Neither search reports a significant new-particle signal. Experimental evidence can strengthen the applicability of a physical model satisfying a theorem’s assumptions; it cannot turn a conditional theorem into an unconditional physical claim.","Ninguna búsqueda comunica una señal significativa de nueva partícula. La evidencia experimental puede reforzar la aplicabilidad de un modelo físico que cumpla las hipótesis de un teorema; no convierte un teorema condicional en una afirmación física incondicional.")}</p>'
        links=[('https://arxiv.org/abs/2512.17856','ATLAS — 2512.17856'),('https://arxiv.org/abs/1911.03947','CMS — 1911.03947'),('https://arxiv.org/abs/1711.04777','Monnier, Moore, Park — 1711.04777'),('https://arxiv.org/abs/2309.03937','Choi et al. — 2309.03937'),('https://arxiv.org/abs/2012.11622','Lee, Tachikawa — 2012.11622'),('../../certificates/index.html',T('Complete certificates, Lean sources and replay instructions','Certificados completos, fuentes Lean e instrucciones de repetición')),('../../guide/'+('es/' if es else '')+'quantization/index.html',T('Quantization guide','Guía de cuantización')),('inputs.json',T('Exact chart inputs and source hash','Entradas exactas de las gráficas y hash de la fuente'))]
        bridge+='<ul>'+''.join(f'<li><a href="{url.replace("../../certificates/","../../proof/")}">{label}</a></li>' for url,label in links)+'</ul></main></body></html>'
        (out/('bridge'+suffix+'.html')).write_text(bridge,encoding='utf-8')
    notes=(old/'proof-notes.html').read_text(encoding='utf-8')
    for report in reports:
        duration=f"{int(report['seconds'])//60}:{int(report['seconds'])%60:02}"
        notes=notes.replace('11:34' if report['language']=='en' else '11:55',duration)
    notes=notes.replace('<main>','<main><p><strong>Scope of these notes:</strong> the four original boundary, profile, trace and family examples. For the added quantization module, the catalogue of 59 Lean declarations and their physical interpretation, see the <a href="bridge.html">14 October analysis</a> or <a href="bridge-es.html" lang="es">análisis en castellano</a>, and the <a href="../../proof/index.html">complete certificate catalogue</a>.</p>',1)
    (out/'proof-notes.html').write_text(notes,encoding='utf-8')
    for name in ['certificates.json','lab-reference.json','certify.py','requirements.txt']:
        shutil.copyfile(old/name,out/name)
    shutil.copyfile(Path(__file__).parent/'inputs.json',out/'inputs.json')
    (out/'README.md').write_text('# Mathematical film — 17 October 2026\n\n46 chapters per language. Chapters 1–43 preserve the previous film; chapters 44–46 explain matched profiles, independent continuum certification and the remaining physical assumptions. Upper limits and measured cross sections remain distinct.\n\nSee render-manifest.json for all media hashes, timings, source provenance and full-decode results. Narration is synthetic. Human listening review is not claimed. Original 12 and 13 October media remain unchanged in the adjacent versioned directory.\n',encoding='utf-8')
